{"implementation": "def solve(case):
    # Validate required fields
    for field in ("nodes", "core_distance", "distances"):
        if field not in case:
            raise ValueError(f"Missing required field: {field}")

    nodes = list(case["nodes"])
    core_distance = case["core_distance"]
    distances = case["distances"]

    if len(nodes) == 0:
        raise ValueError("nodes list is empty")

    for node in nodes:
        if node not in core_distance:
            raise ValueError(f"core_distance missing for node: {node}")

    n = len(nodes)

    # Build mutual-reachability edges
    mr_edges = []
    for entry in distances:
        if len(entry) != 3:
            raise ValueError(f"Invalid distance entry: {entry}")
        u, v, dist = entry[0], entry[1], entry[2]
        if u not in core_distance:
            raise ValueError(f"Node not in core_distance: {u}")
        if v not in core_distance:
            raise ValueError(f"Node not in core_distance: {v}")
        # Canonicalize undirected endpoints
        a, b = (u, v) if u <= v else (v, u)
        mr = max(core_distance[u], core_distance[v], dist)
        mr_edges.append((mr, a, b))

    # Sort by mutual reachability, then first endpoint id, then second endpoint id
    mr_edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find helpers
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        cur = x
        while parent[cur] != root:
            nxt = parent[cur]
            parent[cur] = root
            cur = nxt
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    # Kruskal's MST
    mst_edges = []
    total_weight = 0.0

    for mr, a, b in mr_edges:
        if union(a, b):
            mst_edges.append({"endpoints": [a, b], "weight": mr})
            total_weight += mr
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) < n - 1:
        raise ValueError("Graph is disconnected; MST cannot span all nodes")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
"}
